import React, { ReactNode } from 'react';
import { FileSpreadsheet, FileText, Printer, FileDown, Filter } from 'lucide-react';

export interface ReportShellProps {
  title: string;
  description?: string;
  icon?: React.ElementType;
  /** Filter form row contents (dropdowns, inputs) */
  filterChildren?: ReactNode;
  /** Callback when primary [Filter] button is clicked */
  onFilterSubmit?: (e?: React.FormEvent) => void;
  isFilterLoading?: boolean;
  /** Subheader strip title (defaults to title) */
  bannerTitle?: string;
  /** Metadata audit strip (e.g., branch name, date basis, generated by) */
  metaNotice?: ReactNode;
  /** KPI cards strip */
  kpiStrip?: ReactNode;
  /** Export callbacks */
  onExportExcel?: () => void;
  onExportCsv?: () => void;
  onExportPdf?: () => void;
  onExportPrint?: () => void;
  /** Content: Data Table or custom views */
  children: ReactNode;
}

export const ReportShell: React.FC<ReportShellProps> = ({
  title,
  description,
  icon: Icon,
  filterChildren,
  onFilterSubmit,
  isFilterLoading = false,
  bannerTitle,
  metaNotice,
  kpiStrip,
  onExportExcel,
  onExportCsv,
  onExportPdf,
  onExportPrint,
  children,
}) => {
  return (
    <div className="w-full max-w-full space-y-6 text-slate-800 font-sans pb-12">
      {/* ── 1. Page Header (Frosted Glassmorphism Banner) ── */}
      <div className="relative overflow-hidden rounded-[24px] border border-white/90 bg-white/75 p-6 backdrop-blur-2xl shadow-[0_10px_35px_rgba(35,21,29,0.035),inset_0_1.5px_2px_rgba(255,255,255,1)]">
        <div className="pointer-events-none absolute -right-20 -top-20 h-64 w-64 rounded-full bg-gradient-to-br from-[#B82E69]/10 via-[#D94883]/5 to-transparent blur-3xl" />

        <div className="relative flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-3.5">
            {Icon && (
              <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-[#B82E69] to-[#9D2558] text-white shadow-lg shadow-[#B82E69]/25">
                <Icon className="h-6 w-6" />
              </div>
            )}
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-2xl font-bold tracking-tight text-[#18191B]">{title}</h1>
                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-[#FDF2F5] text-[#B82E69] border border-[#B82E69]/20 uppercase tracking-wider">
                  Report
                </span>
              </div>
              {description && <p className="text-xs text-[#78616C] font-medium mt-0.5">{description}</p>}
            </div>
          </div>
        </div>
      </div>

      {/* ── 2. Top Filter Header Row (Frosted Glass Container) ── */}
      {filterChildren && (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            onFilterSubmit?.(e);
          }}
          className="rounded-[24px] border border-white/90 bg-white/75 p-5 md:p-6 backdrop-blur-2xl shadow-[0_10px_35px_rgba(35,21,29,0.035),inset_0_1.5px_2px_rgba(255,255,255,1)] print:hidden"
        >
          <div className="flex flex-wrap items-end gap-3.5">
            <div className="flex-1 flex flex-wrap items-end gap-3.5 min-w-[280px]">
              {filterChildren}
            </div>

            {/* Primary [Filter] Trigger Button */}
            <div className="shrink-0">
              <button
                type="submit"
                disabled={isFilterLoading}
                className="h-9 px-5 bg-[#B82E69] hover:bg-[#A02358] active:bg-[#851C47] text-white rounded-xl text-xs font-semibold flex items-center justify-center gap-2 shadow-xs transition-all cursor-pointer disabled:opacity-70"
              >
                <Filter className="w-3.5 h-3.5 fill-current" />
                <span>{isFilterLoading ? 'Loading…' : 'Apply Filters'}</span>
              </button>
            </div>
          </div>
        </form>
      )}

      {/* ── 3. Meta Notice / Audit Line ── */}
      {metaNotice && (
        <div className="px-2 text-xs text-[#78616C] flex items-center gap-2">
          {metaNotice}
        </div>
      )}

      {/* ── 4. KPI Summary Strip (Optional) ── */}
      {kpiStrip && <div>{kpiStrip}</div>}

      {/* ── 5. Table Header Action Strip ── */}
      <div className="flex flex-wrap items-center justify-between gap-3 px-1">
        <div className="text-sm font-bold text-[#18191B] tracking-tight">
          {bannerTitle || title}
        </div>

        {/* Export Actions Strip */}
        <div className="flex items-center gap-2 print:hidden">
          {onExportExcel && (
            <button
              type="button"
              onClick={onExportExcel}
              className="h-8 px-3 bg-emerald-50 hover:bg-emerald-100 text-emerald-700 border border-emerald-200/80 rounded-xl text-xs font-semibold flex items-center gap-1.5 shadow-2xs transition-colors cursor-pointer"
              title="Export data to Excel spreadsheet"
            >
              <FileSpreadsheet className="w-3.5 h-3.5 text-emerald-600" />
              <span>Excel</span>
            </button>
          )}
          {onExportCsv && (
            <button
              type="button"
              onClick={onExportCsv}
              className="h-8 px-3 bg-cyan-50 hover:bg-cyan-100 text-cyan-700 border border-cyan-200/80 rounded-xl text-xs font-semibold flex items-center gap-1.5 shadow-2xs transition-colors cursor-pointer"
              title="Export raw data to CSV file"
            >
              <FileText className="w-3.5 h-3.5 text-cyan-600" />
              <span>CSV</span>
            </button>
          )}
          {onExportPdf && (
            <button
              type="button"
              onClick={onExportPdf}
              className="h-8 px-3 bg-rose-50 hover:bg-rose-100 text-rose-700 border border-rose-200/80 rounded-xl text-xs font-semibold flex items-center gap-1.5 shadow-2xs transition-colors cursor-pointer"
              title="Download or Print PDF Document"
            >
              <FileDown className="w-3.5 h-3.5 text-rose-600" />
              <span>PDF</span>
            </button>
          )}
          {onExportPrint && (
            <button
              type="button"
              onClick={onExportPrint}
              className="h-8 px-3 bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-200/80 rounded-xl text-xs font-semibold flex items-center gap-1.5 shadow-2xs transition-colors cursor-pointer"
              title="Open browser print dialog"
            >
              <Printer className="w-3.5 h-3.5 text-slate-600" />
              <span>Print</span>
            </button>
          )}
        </div>
      </div>

      {/* ── 6. Main Report Body (Landscape Table Container) ── */}
      <div className="w-full">{children}</div>
    </div>
  );
};
